import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { expect, it } from 'vitest';
import { NicknameForm } from './Solution';

interface FormState {
  attempts: number;
  error: string | null;
  saved: string | null;
}

/** 受控校验器：什么时候放行由用例决定，顺便量出"有没有并发"。 */
function makeChecker() {
  const seen: { name: string; prevAttempts: number }[] = [];
  const inflight = { now: 0, max: 0 };
  const deferreds: { resolve: (v: FormState) => void }[] = [];
  const check = (name: string, previous: FormState) => {
    seen.push({ name, prevAttempts: previous ? previous.attempts : -1 });
    inflight.now += 1;
    inflight.max = Math.max(inflight.max, inflight.now);
    return new Promise<FormState>((resolve) => {
      deferreds.push({
        resolve: (v: FormState) => {
          inflight.now -= 1;
          resolve(v);
        },
      });
    });
  };
  const type = (value: string) => {
    fireEvent.change(screen.getByTestId('nickname'), { target: { value } });
  };
  /** 状态更新要等 React 提交；判分只看提交后的 DOM，不猜微任务时序。 */
  const text = async (testid: string, value: string) => {
    await waitFor(() => expect(screen.getByTestId(testid).textContent).toBe(value));
  };
  const submit = () => {
    fireEvent.submit(screen.getByTestId('form'));
  };
  return { check, seen, inflight, deferreds, type, submit, text };
}

it('初始无错误无已保存文案且按钮可用', () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  expect(screen.getByTestId('error').textContent).toBe('');
  expect(screen.getByTestId('saved').textContent).toBe('');
  expect(screen.getByTestId('attempts').textContent).toBe('0');
  expect(screen.getByTestId('submit').textContent).toBe('保存');
  expect(screen.getByTestId('submit').hasAttribute('disabled')).toBe(false);
  expect(c.seen.length).toBe(0);
});

it('单次提交期间按钮禁用且子组件文案变保存中', async () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  c.type('ada');
  c.submit();
  expect(c.seen.length).toBe(1);
  expect(c.seen[0].name).toBe('ada');
  expect(screen.getByTestId('submit').textContent).toBe('保存中');
  expect(screen.getByTestId('submit').hasAttribute('disabled')).toBe(true);
  await act(async () => {
    c.deferreds[0].resolve({ attempts: 1, error: null, saved: 'ada' });
    await new Promise((r) => setTimeout(r, 0));
  });
  expect(screen.getByTestId('submit').textContent).toBe('保存');
  expect(screen.getByTestId('submit').hasAttribute('disabled')).toBe(false);
});

it('空昵称被前端拦截不发请求', async () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  c.submit();
  expect(c.seen.length).toBe(0);
  await c.text('error', '请输入昵称');
  expect(screen.getByTestId('attempts').textContent).toBe('0');
});

it('校验失败回显服务端错误并累加 attempts', async () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  c.type('ada');
  c.submit();
  await act(async () => {
    c.deferreds[0].resolve({ attempts: 1, error: '昵称已被占用', saved: null });
    await new Promise((r) => setTimeout(r, 0));
  });
  await c.text('error', '昵称已被占用');
  expect(screen.getByTestId('saved').textContent).toBe('');
  expect(screen.getByTestId('attempts').textContent).toBe('1');
  expect(screen.getByTestId('submit').hasAttribute('disabled')).toBe(false);
});

it('重复提交排队串行不并发且 previousState 链正确', async () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  c.type('ada');
  c.submit();
  c.type('bob');
  c.submit();
  expect(c.seen.length).toBe(1);
  await act(async () => {
    c.deferreds[0].resolve({ attempts: 1, error: null, saved: 'ada' });
    await new Promise((r) => setTimeout(r, 0));
  });
  await waitFor(() => expect(c.seen.length).toBe(2));
  expect(c.seen[1].name).toBe('bob');
  expect(c.seen[1].prevAttempts).toBe(1);
  expect(c.inflight.max).toBe(1);
  // 收尾：把队列里第二次 action 结掉，别把未完成的 Action 留给下一个用例
  act(() => c.deferreds[1].resolve({ attempts: 2, error: null, saved: 'bob' }));
  await c.text('saved', 'bob');
});

it('保存成功后展示 saved 且按钮恢复可用', async () => {
  const c = makeChecker();
  render(<NicknameForm check={c.check} />);
  c.type('ada');
  c.submit();
  await act(async () => {
    c.deferreds[0].resolve({ attempts: 1, error: null, saved: 'ada' });
    await new Promise((r) => setTimeout(r, 0));
  });
  await c.text('saved', 'ada');
  expect(screen.getByTestId('attempts').textContent).toBe('1');
  expect(screen.getByTestId('error').textContent).toBe('');
  expect(screen.getByTestId('error').textContent).toBe('');
  expect(screen.getByTestId('submit').hasAttribute('disabled')).toBe(false);
});

