import { useActionState } from 'react';
import { useFormStatus } from 'react-dom';
import type { ReactNode } from 'react';

export interface FormState {
  attempts: number;
  error: string | null;
  saved: string | null;
}

export interface NicknameFormProps {
  check: (name: string, previous: FormState) => Promise<FormState>;
}

const IDLE: FormState = { attempts: 0, error: null, saved: null };

/** useFormStatus 只有在 <form> 的后代组件里才拿得到本表单状态。 */
function SubmitButton() {
  const { pending } = useFormStatus();
  return (
    <button data-testid="submit" type="submit" disabled={pending}>
      {pending ? '保存中' : '保存'}
    </button>
  );
}

export function NicknameForm({ check }: NicknameFormProps): ReactNode {
  const [state, dispatch] = useActionState(async (previous: FormState, payload: FormData) => {
    const name = String(payload.get('nickname') ?? '').trim();
    // 可预期的校验失败要 return 进 state，不要用 throw 表达业务分支
    if (!name) return { ...previous, error: '请输入昵称' };
    const next = await check(name, previous);
    return { ...next, error: next.error ?? null };
  }, IDLE);

  return (
    <form data-testid="form" action={dispatch as unknown as (payload: FormData) => void}>
      <input data-testid="nickname" name="nickname" defaultValue="" />
      <span data-testid="error">{state.error ?? ''}</span>
      <span data-testid="saved">{state.saved ?? ''}</span>
      <span data-testid="attempts">{state.attempts}</span>
      <SubmitButton />
    </form>
  );
}

