import { useState } from 'react';

export function NicknameForm({ check }) {
  const [attempts, setAttempts] = useState(0);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState('');
  const [saving, setSaving] = useState(false);

  async function onSubmit(event) {
    event.preventDefault();
    setSaving(true);
    const name = new FormData(event.currentTarget).get('nickname');
    setAttempts((n) => n + 1);
    const next = await check(name, { attempts, error: null, saved: null });
    setSaving(false);
    setError(next.error ?? '');
    setSaved(next.saved ?? '');
  }

  return (
    <form data-testid="form" onSubmit={onSubmit}>
      <input data-testid="nickname" name="nickname" defaultValue="" />
      <span data-testid="error">{error}</span>
      <span data-testid="saved">{saved}</span>
      <span data-testid="attempts">{attempts}</span>
      <button data-testid="submit" type="submit" disabled={saving}>
        {saving ? '保存中' : '保存'}
      </button>
    </form>
  );
}
